              border: qrSubTab === "all" ? "none" : `1px solid ${C.line}`,
              background: qrSubTab === "all" ? C.ink : "#fff", color: qrSubTab === "all" ? "#fff" : C.ink, fontWeight: qrSubTab === "all" ? 600 : 400,
