                    <button onClick={() => clearSoldPrice(l.id)} style={{ fontSize: 11, padding: "3px 8px", borderRadius: 4, cursor: "pointer", border: "none", background: "#FBE4E3", color: "#A32D2D" }}>Clear price</button>
